const form=document.getElementById('viewer-form'),message=document.getElementById('user-message');
(async()=>{try{const r=await fetch('/api/auth/viewers');if(r.status===401){location.replace('/login.html?next=%2Fusers.html');return;}const d=await r.json();if(!r.ok)throw Error(d.error);if(d.users.some(u=>u.username.toLowerCase()==='gerencia.com')){message.textContent='GERENCIA.COM ya existe con permiso de solo visualización. No se cambió su contraseña.';return;}form.hidden=false;message.textContent='Define la contraseña y confirma la creación.';}catch(e){message.textContent=e.message;}})();
form.addEventListener('submit',async e=>{e.preventDefault();const password=document.getElementById('new-password'),confirm=document.getElementById('confirm-password'),button=document.getElementById('create-viewer');if(password.value!==confirm.value){message.textContent='Las contraseñas no coinciden.';return;}button.disabled=true;try{const r=await fetch('/api/auth/viewers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'GERENCIA.COM',password:password.value})});const d=await r.json();if(!r.ok)throw Error(d.error);form.reset();form.hidden=true;message.textContent='GERENCIA.COM creado. Acceso de solo visualización a ambas obras. Ingresa con ese usuario desde la página de acceso.';}catch(e){message.textContent=e.message;}finally{password.value='';confirm.value='';button.disabled=false;}});
